Map m = ctx.mongo;
if (m.t instanceof Map && m.t.get('$date') != null) { ctx._ts = m.t.get('$date').toString(); }
if (m.s != null) { ctx._sev = m.s.toString(); }
if (m.c != null) { m.component = m.c; }
if (m.ctx != null) { m.context = m.ctx; }
if (m.msg != null) { ctx.message = m.msg; }
if (m.attr instanceof Map && m.attr.durationMillis != null) {
  if (ctx.event == null) { ctx.event = new HashMap(); }
  ctx.event.duration = Math.round(((Number) m.attr.durationMillis).doubleValue() * 1000000.0);
}
m.remove('t'); m.remove('s'); m.remove('c'); m.remove('ctx'); m.remove('msg');

String s = ctx._sev;
String l = 'info';
if (s == 'F') { l = 'fatal'; } else if (s == 'E') { l = 'error'; } else if (s == 'W') { l = 'warning'; }
else if (s == 'I') { l = 'info'; } else if (s.startsWith('D')) { l = 'debug'; }
Map lg = new HashMap(); lg.put('level', l); ctx.log = lg;
